-- Generated from the checked-in product fallbacks.
-- After this initial seed, Supabase is the runtime source of truth.
do $migration$
declare
  catalog jsonb := $catalog$[{"id":"shield","slug":"shield","name":"Shield","tagline":"Protege tu identidad antes de compartir un documento.","tagline_en":"Protect your identity before sharing a document.","shortDescription":"Oculta datos personales innecesarios en documentos generales o de identidad y comparte solo la información que cada trámite necesita.","shortDescription_en":"Hide unnecessary personal data in general or identity documents and share only what each process requires.","longDescription":"Shield protege tu identidad cuando una inmobiliaria, agencia de viajes, profesional o entidad te pide documentación. Prepara contratos, nóminas, extractos, reservas o documentos de identidad para alquileres, viajes y procesos legales; oculta lo que el destinatario no necesita y exporta una copia verificada sin modificar el original.","longDescription_en":"Shield protects your identity when a landlord, travel provider, professional, or organization asks for documentation. Prepare contracts, payslips, statements, bookings, or identity documents for rentals, travel, and legal processes; hide what the recipient does not need and export a verified copy without changing the original.","problem":"Compartir un documento completo puede revelar más información de la necesaria: domicilio, número de identificación, firma, datos bancarios o códigos personales. Una captura improvisada o un rectángulo dentro de un PDF tampoco garantiza que esos datos dejen de ser recuperables.","problem_en":"Sharing a complete document can expose more information than necessary: your address, identification number, signature, bank details, or personal codes. A quick screenshot or a rectangle placed over a PDF does not guarantee that the hidden data cannot be recovered.","benefits":["Protege tu identidad: Comparte documentos de identificación sin entregar todos tus datos personales.","Comparte solo lo necesario: Adapta cada copia al alquiler, viaje, trámite legal o destinatario concreto.","Salida comprobada: La exportación rasteriza el resultado y busca texto residual recuperable.","Privacidad desde el origen: Los documentos, el OCR, las máscaras y la exportación se procesan en el dispositivo."],"benefits_en":["Protect your identity: Share identification documents without disclosing all your personal data.","Share only what is needed: Tailor each copy to a rental, trip, legal process, or specific recipient.","Checked output: Export flattens the result and checks for recoverable residual text.","Private by design: Documents, OCR, masks, and exports are processed on device."],"features":["Captura e importación: Cámara, escáner, Fotos, Archivos, PDF y extensión Compartir.","OCR conservador: Sugerencias para identidad, email, teléfono, IBAN y tarjetas, siempre sujetas a revisión.","Editor de precisión: Máscaras editables, documentos multipágina, estilos y ajustes de imagen.","Flujos repetibles: Plantillas semánticas y procesamiento por lotes en Shield Pro.","Exportación segura: Copias PDF o imagen rasterizadas con verificación posterior.","Privacidad local: Cifrado en reposo, Vault, archivos temporales protegidos y sin seguimiento publicitario.","Accesibilidad nativa: iPhone, iPad, teclado, VoiceOver y Dynamic Type."],"features_en":["Capture and import: Camera, scanner, Photos, Files, PDF, and the Share Extension.","Conservative OCR: Suggestions for identity, email, phone, IBAN, and card data, always subject to review.","Precision editor: Editable masks, multi-page documents, styles, and image adjustments.","Repeatable workflows: Semantic templates and batch processing in Shield Pro.","Secure export: Rasterized PDF or image copies with post-export verification.","Local privacy: Encryption at rest, Vault, protected temporary files, and no advertising tracking.","Native accessibility: iPhone, iPad, keyboard, VoiceOver, and Dynamic Type."],"audience":"Personas que deben compartir documentos generales o de identificación con inmobiliarias, alojamientos, agencias, profesionales, empresas o entidades durante alquileres, viajes, procesos legales y otros trámites puntuales.","audience_en":"People who need to share general or identity documents with landlords, accommodation providers, agencies, professionals, companies, or organizations during rentals, travel, legal processes, and other occasional procedures.","status":"coming_soon","featured":true,"category":"Productividad","platform":["iOS","iPadOS"],"supportEmail":"romerodev.app+shield@gmail.com","iconUrl":"assets/images/shield/shield-icon.png","coverImageUrl":"assets/images/shield/screens/simulator/01-home_es.jpg","screenshots":["01-home","02-capture","03-editor","04-ocr","05-export","07-vault","08-batch","10-settings"],"primaryCtaLabel":"Solicitar acceso a la beta","primaryCtaLabel_en":"Request beta access","primaryCtaUrl":"/contact","secondaryCtaLabel":"Ver funciones","secondaryCtaLabel_en":"View features","secondaryCtaUrl":"/apps/shield#features","colorPrimary":"#e6b900","colorSecondary":"#22c55e","updatedAt":"2026-07-16","seo":{"title":"Shield - Protege tu identidad al compartir documentos | RomeroDev","description":"Oculta datos personales en documentos de identidad, alquileres, viajes y trámites legales. Comparte únicamente lo necesario con Shield."},"faq":[{"question":"¿Shield sube mis documentos a un servidor?","question_en":"Does Shield upload my documents to a server?","answer":"No. Los documentos, imágenes, OCR, máscaras y exportaciones se procesan en el dispositivo. La sincronización opcional con iCloud guarda solo un índice técnico minimizado en tu base privada de CloudKit; el contenido y los resultados OCR permanecen locales.","answer_en":"No. Documents, images, OCR, masks, and exports are processed on device. Optional iCloud sync stores only a minimized technical index in your private CloudKit database; content and OCR results remain local."},{"question":"¿Qué significa exportación verificada?","question_en":"What does verified export mean?","answer":"Shield rasteriza la copia y comprueba propiedades técnicas del resultado, incluido el texto residual recuperable. La verificación no puede saber si olvidaste seleccionar un dato sensible, por lo que siempre debes revisar todas las páginas.","answer_en":"Shield flattens the copy and checks technical properties of the output, including recoverable residual text. Verification cannot know whether you forgot to select sensitive data, so every page still requires review."},{"question":"¿El OCR oculta todos los datos automáticamente?","question_en":"Does OCR hide every sensitive item automatically?","answer":"No. El OCR ofrece sugerencias conservadoras para ayudarte a localizar campos, pero puede cometer errores u omisiones. Tú decides qué zonas se ocultan y confirmas el resultado antes de exportar.","answer_en":"No. OCR offers conservative suggestions to help locate fields, but it can make mistakes or omissions. You decide which areas are hidden and confirm the result before export."},{"question":"¿En qué situaciones protege mi identidad Shield?","question_en":"When can Shield help protect my identity?","answer":"Cuando necesitas enviar documentación a una inmobiliaria, alojamiento, agencia, profesional, empresa o entidad. Puedes preparar documentos de identidad, contratos, nóminas, extractos, reservas y otros justificantes para alquileres, viajes o procesos legales, ocultando los datos que ese destinatario no necesita.","answer_en":"When you need to send documentation to a landlord, accommodation provider, agency, professional, company, or organization. You can prepare identity documents, contracts, payslips, statements, bookings, and other evidence for rentals, travel, or legal processes while hiding data that the recipient does not need."},{"question":"¿Qué incluye Shield Free?","question_en":"What is included in Shield Free?","answer":"Hasta 10 documentos activos, captura e importación, máscaras manuales, sugerencias OCR, almacenamiento cifrado y exportación verificada sin marca de agua forzada. Las funciones de seguridad esenciales no son exclusivas de Pro.","answer_en":"Up to 10 active documents, capture and import, manual masks, OCR suggestions, encrypted storage, and verified export without a forced watermark. Essential safety features are not exclusive to Pro."},{"question":"¿Funciona en iPad y con tecnologías de accesibilidad?","question_en":"Does it work on iPad and with accessibility technologies?","answer":"Sí. Shield es una app universal para iPhone y iPad, con soporte para teclado, VoiceOver y Dynamic Type.","answer_en":"Yes. Shield is a universal iPhone and iPad app with keyboard, VoiceOver, and Dynamic Type support."}],"legal":{"privacy":{"title":"Política de privacidad de Shield","title_en":"Shield Privacy Policy","updatedAt":"2026-07-16","body":["Esta política explica cómo Shield, desarrollada por Lester Romero Bernardo (RomeroDev), trata la información cuando utilizas la aplicación. Apple trata de forma independiente las compras del App Store, los datos de la cuenta Apple y los servicios de iCloud conforme a sus propias políticas.","## 1. Procesamiento en el dispositivo","La importación de documentos, captura con cámara, escaneo, ajustes de imagen, OCR, máscaras y exportación se ejecutan en tu dispositivo. Shield no opera un backend publicitario o analítico, no crea perfiles publicitarios ni rastrea usuarios entre aplicaciones o sitios web.","## 2. Almacenamiento local y seguridad","Los originales importados, archivos de trabajo, cachés de renderizado y telemetría local limitada se cifran en reposo mediante claves vinculadas al dispositivo, protegidas por el Llavero y la protección de datos de iOS. La Bóveda utiliza una clave separada vinculada al dispositivo y la autenticación configurada. Estas claves no están diseñadas para migrar a otro dispositivo.","## 3. Índice opcional de iCloud","Si una persona usuaria de Pro activa expresamente iCloud, Shield guarda únicamente un índice técnico mínimo del proyecto en su base privada de CloudKit. Las imágenes, el contenido PDF, el texto OCR, los títulos introducidos y el estado de la Bóveda permanecen locales. Apple trata los datos privados de CloudKit como proveedor de iCloud.","## 4. Permisos y proveedores de Archivos","Cámara, Fotos, biometría, Archivos, Compartir e iCloud se utilizan únicamente para las funciones solicitadas y permanecen sujetos a los controles del sistema. Cuando eliges un proveedor externo mediante el selector Archivos de Apple, Shield recibe solo el archivo seleccionado y no almacena tokens OAuth del proveedor.","## 5. Diagnósticos","Los diagnósticos de MetricKit y la telemetría local protegida y rotatoria pueden incluir versiones de la app, identificadores de eventos, duraciones, recuentos y categorías de dispositivo. Shield no los sube y excluye títulos, texto OCR, nombres de archivo, URL, identificadores de documentos, estado del PIN e imágenes.","## 6. Conservación y eliminación","Los proyectos permanecen hasta que los eliminas o seleccionas Eliminar todos los documentos. Las exportaciones temporales se protegen y eliminan al finalizar el flujo. Desinstalar la app elimina su contenedor local conforme al funcionamiento de iOS y las copias de seguridad. Los registros privados de CloudKit pueden requerir un borrado separado o el uso de los controles de iCloud.","## 7. Opciones y derechos","Puedes revocar permisos opcionales en Ajustes de iOS, desactivar el índice de iCloud y eliminar proyectos. Como el contenido principal permanece en el dispositivo, el desarrollador normalmente no puede acceder, exportar, corregir ni recuperar ese contenido.","Cuando resulte aplicable, puedes solicitar acceso, rectificación, supresión, limitación, oposición, portabilidad o retirada del consentimiento escribiendo al contacto indicado. También puedes reclamar ante la Agencia Española de Protección de Datos o la autoridad competente de tu lugar de residencia.","## 8. Menores","Shield es una utilidad documental general y no está dirigida a menores. No trates información sensible de menores sin autoridad legal y salvaguardas adecuadas.","## 9. Seguridad y limitaciones","Ningún sistema elimina todos los riesgos. Debes proteger el código del dispositivo y la cuenta Apple, conservar los originales necesarios, verificar los destinatarios y revisar cada página exportada. El reconocimiento automático puede omitir información sensible.","## 10. Cambios y contacto","Los cambios relevantes se reflejarán mediante una nueva fecha de entrada en vigor y, cuando proceda, un aviso en la aplicación.","Responsable del tratamiento: **Lester Romero Bernardo (RomeroDev)**","Domicilio: **Calle Madre Juana María Condesa Lluch 6, Valencia, España**","Contacto de privacidad: **romerodev.app+shield@gmail.com**"],"body_en":["This policy explains how Shield, developed by Lester Romero Bernardo (RomeroDev), handles information when you use the application. Apple independently processes App Store purchases, Apple Account data, and iCloud services under its own policies.","## 1. On-device processing","Document import, camera capture, scanning, image adjustments, OCR, masking, and export run on your device. Shield does not operate an advertising or analytics backend, create advertising profiles, or track users across apps or websites.","## 2. Local storage and security","Imported originals, working files, render caches, and bounded local telemetry are encrypted at rest using device-bound keys protected by Keychain and iOS data protection. The Vault uses a separate device-bound key and configured authentication. Device-only keys are not designed to migrate to another device.","## 3. Optional iCloud index","If a Pro user explicitly enables iCloud sync, Shield stores only a minimized technical project index in that user's private CloudKit database. Document images, PDF content, OCR text, user-entered titles, and Vault state remain local. Apple processes private CloudKit data as the user's iCloud provider.","## 4. Permissions and Files providers","Camera, Photos, biometrics, Files, Share Sheet, and iCloud access are used only for features the user requests and remain subject to system controls. When a user chooses a third-party storage provider through Apple's Files picker, Shield receives only the selected file and stores no provider OAuth token.","## 5. Diagnostics","MetricKit diagnostics and protected, rotating local telemetry may include app versions, event identifiers, durations, counts, and device-class buckets. Shield does not upload them and excludes document titles, OCR text, filenames, URLs, document IDs, PIN state, and image content.","## 6. Retention and deletion","Projects remain until the user deletes them or selects Delete all documents. Temporary exports are protected and removed when the export or share flow ends. Removing the app deletes its local container subject to iOS and backup behavior. Private CloudKit records may require separate deletion or iCloud account controls.","## 7. Choices and rights","Users can revoke optional permissions in iOS Settings, disable iCloud index sync, and delete projects. Because core document content stays on device, the developer normally cannot access, export, correct, or recover it.","Where applicable, you may request access, rectification, deletion, restriction, objection, portability, or withdrawal of consent by writing to the contact below. You may also lodge a complaint with the Spanish Data Protection Agency or the competent authority where you live.","## 8. Children","Shield is a general document utility and is not directed to children. Do not process a child's sensitive information without lawful authority and appropriate safeguards.","## 9. Security and limitations","No security system eliminates every risk. Users must protect their device passcode and Apple Account, retain required originals, verify recipients, and review every exported page. Automated recognition can miss sensitive information.","## 10. Changes and contact","Material changes will be reflected by a new effective date and, when appropriate, an in-app notice.","Data controller: **Lester Romero Bernardo (RomeroDev)**","Address: **Calle Madre Juana María Condesa Lluch 6, Valencia, Spain**","Privacy contact: **romerodev.app+shield@gmail.com**"]},"terms":{"title":"Términos de uso de Shield","title_en":"Shield Terms of Use","updatedAt":"2026-07-16","body":["Estos términos regulan el uso de Shield. Se mantienen los derechos imperativos de las personas consumidoras y los términos aplicables del App Store de Apple.","## 1. Aceptación y capacidad","Al descargar o utilizar Shield aceptas estos términos. Debes tener capacidad legal para celebrar este acuerdo. Si actúas en nombre de una organización, confirmas que tienes autoridad para vincularla.","## 2. Licencia","Recibes una licencia limitada, personal, no exclusiva, intransferible y revocable para utilizar Shield en dispositivos Apple asociados a tu cuenta del App Store, conforme a estos términos y las reglas de uso de Apple. Shield se licencia, no se vende.","## 3. Tus documentos","Conservas los derechos sobre el contenido que importas o creas y confirmas que dispones de los derechos, consentimiento u otra base jurídica necesarios para tratarlo. Shield no adquiere la propiedad de tus documentos.","## 4. Uso aceptable","No utilices Shield para fraude, suplantación, falsificación, infracción, acoso, malware, vigilancia ilícita, divulgación no autorizada, evasión de obligaciones legales o interferencia con la aplicación. La ingeniería inversa está prohibida salvo cuando la ley aplicable la permita expresamente.","## 5. Límites del OCR y la exportación","El OCR, la detección de entidades, las máscaras y la verificación técnica pueden fallar o producir resultados falsos. Una exportación verificada significa que el archivo generado superó las comprobaciones técnicas de Shield; no significa que se hayan detectado o seleccionado todos los datos sensibles. Debes inspeccionar cada página, conservar los originales necesarios y determinar si la divulgación es lícita y aceptada por el destinatario previsto.","## 6. Compras","Los productos Pro se venden mediante el sistema de compras integradas de Apple. Apple controla los precios, impuestos, moneda, autorización de pago, facturación y reembolsos. Las condiciones de las suscripciones y del producto vitalicio se recogen en las Condiciones de suscripción independientes.","## 7. Propiedad intelectual","El software, diseño, marca, documentación y contenido original de Shield están protegidos por las leyes de propiedad intelectual. Los servicios de Apple, símbolos del sistema y componentes de terceros permanecen sujetos a sus respectivas condiciones.","## 8. Disponibilidad, garantías y responsabilidad","Shield incluye las garantías exigidas por la legislación aplicable. En la máxima medida legalmente permitida, se proporciona según disponibilidad, sin garantías de funcionamiento ininterrumpido, detección perfecta, idoneidad para un fin regulado, aceptación por un destinatario o ausencia de pérdida de datos. La responsabilidad no se excluye cuando la ley prohíbe su exclusión.","## 9. Suspensión y terminación","Puedes dejar de utilizar Shield en cualquier momento. El acceso puede limitarse para proteger a las personas usuarias, cumplir la ley, abordar usos indebidos o mantener los servicios. Dejar de usar o eliminar la aplicación no cancela una suscripción del App Store.","## 10. Asesoramiento, cambios y legislación","Shield no presta asesoramiento jurídico, médico, financiero, normativo, de identidad, ciberseguridad o conservación. Las condiciones actualizadas mostrarán una nueva fecha de entrada en vigor.","Estos términos se rigen por las leyes de **España y la Comunidad Valenciana**, sin perjuicio de los derechos imperativos de las personas consumidoras. Las controversias se someterán a los tribunales legalmente competentes.","Proveedor: **Lester Romero Bernardo (RomeroDev)**","Domicilio: **Calle Madre Juana María Condesa Lluch 6, Valencia, España**","Contacto: **romerodev.app+shield@gmail.com**"],"body_en":["These terms govern use of Shield. Mandatory consumer rights and Apple's applicable App Store terms continue to apply.","## 1. Acceptance and eligibility","By downloading or using Shield, you agree to these terms. You must be legally able to enter this agreement. If you act for an organization, you confirm that you have authority to bind it.","## 2. License","You receive a limited, personal, non-exclusive, non-transferable, revocable license to use Shield on Apple devices associated with your App Store account, subject to these terms and Apple's usage rules. Shield is licensed, not sold.","## 3. Your documents","You retain rights in content you import or create and confirm you have the rights, consent, or other lawful basis needed to process it. Shield does not acquire ownership of your documents.","## 4. Acceptable use","Do not use Shield for fraud, impersonation, falsification, infringement, harassment, malware, unlawful surveillance, unauthorized disclosure, evasion of legal obligations, or interference with the app. Reverse engineering is prohibited except where applicable law expressly permits it.","## 5. OCR and export limitations","OCR, entity detection, masks, and technical verification can fail or produce false results. A verified export means the generated file passed Shield's technical checks; it does not mean every sensitive item was detected or selected. Users must inspect every page, retain required originals, and determine whether disclosure is lawful and accepted by the intended recipient.","## 6. Purchases","Pro products are sold through Apple's in-app purchase system. Apple controls prices, taxes, currency, payment authorization, billing, and refunds. Subscription and lifetime-product conditions are set out in the separate Subscription Terms.","## 7. Intellectual property","Shield's software, design, branding, documentation, and original content are protected by intellectual-property laws. Apple services, system symbols, and third-party components remain subject to their respective terms.","## 8. Availability, warranties, and liability","Shield includes warranties required by applicable law. To the maximum extent legally permitted, it is otherwise provided as available without guarantees of uninterrupted operation, perfect detection, fitness for a regulated purpose, acceptance by a recipient, or freedom from data loss. Liability is not excluded where the law prohibits exclusion.","## 9. Suspension and termination","You may stop using Shield at any time. Access may be limited to protect users, comply with law, address misuse, or maintain services. Stopping use or deleting the app does not cancel an App Store subscription.","## 10. Professional advice, changes, and governing law","Shield does not provide legal, medical, financial, compliance, identity, cybersecurity, or retention advice. Updated terms will show a new effective date.","These terms are governed by the laws of **Spain and Comunidad Valenciana**, without prejudice to mandatory consumer rights. Disputes shall be submitted to the legally competent courts.","Provider: **Lester Romero Bernardo (RomeroDev)**","Address: **Calle Madre Juana María Condesa Lluch 6, Valencia, Spain**","Contact: **romerodev.app+shield@gmail.com**"]},"subscriptions":{"title":"Condiciones de suscripción de Shield","title_en":"Shield Subscription Terms","updatedAt":"2026-07-16","body":["Estas condiciones complementan los Términos de uso de Shield para las suscripciones Shield Pro y el desbloqueo vitalicio.","## 1. Productos y precio","Shield puede ofrecer suscripciones mensuales y anuales autorrenovables y un desbloqueo vitalicio de pago único. El producto, duración, precio localizado, funciones incluidas y oferta mostrados por el App Store antes de confirmar son los que rigen la compra.","## 2. Pago","El pago se carga en la cuenta Apple de la persona usuaria tras la confirmación. Apple gestiona métodos de pago, impuestos, moneda y recibos. Shield no recibe los datos completos de la tarjeta.","## 3. Renovación","Las suscripciones se renuevan automáticamente por el mismo periodo salvo cancelación al menos 24 horas antes de que termine el periodo actual. Apple puede efectuar el cargo dentro de las 24 horas anteriores a la renovación al precio mostrado para el siguiente periodo, sujeto a los avisos exigidos y la legislación aplicable.","## 4. Pruebas y ofertas","Apple determina la elegibilidad y muestra la duración y el precio posterior a la oferta antes de confirmar. Salvo cancelación antes de su finalización, una prueba elegible se convierte en la suscripción de pago mostrada. La parte no utilizada de una prueba puede perderse al adquirir otro plan.","## 5. Gestión, cancelación y restauración","Puedes gestionar o cancelar la suscripción en Ajustes de iOS, dentro de Cuenta Apple y Suscripciones, o mediante la página de suscripciones del App Store. Eliminar Shield no cancela la suscripción. La cancelación detiene futuras renovaciones y el acceso normalmente continúa hasta que termina el periodo pagado. Puedes restaurar las compras desde Shield con la cuenta Apple que realizó la compra.","## 6. Reembolsos y facturación","Apple gestiona reembolsos, disputas de facturación, periodos de gracia, reintentos de pago y revocaciones conforme a sus políticas y la legislación aplicable. Los derechos imperativos de reembolso y desistimiento permanecen inalterados.","## 7. Desbloqueo vitalicio","El desbloqueo vitalicio es una compra no consumible que concede las funciones Pro asociadas durante la vida útil soportada de Shield, no durante la vida biológica de la persona compradora. No promete futuros productos, servicios de terceros, planes para equipos o servicios con precio independiente.","## 8. Cambios","Apple y el desarrollador pueden modificar futuros precios, planes o funciones incluidas. Apple proporciona los avisos y flujos de consentimiento exigidos para aumentos del precio de una suscripción. Los derechos no consumibles ya adquiridos y los derechos imperativos permanecen inalterados.","## 9. Contacto","Proveedor: **Lester Romero Bernardo (RomeroDev)**","Domicilio: **Calle Madre Juana María Condesa Lluch 6, Valencia, España**","Soporte: **romerodev.app+shield@gmail.com**"],"body_en":["These conditions supplement the Shield Terms of Use for Shield Pro subscriptions and the lifetime unlock.","## 1. Products and price","Shield may offer monthly and annual auto-renewable subscriptions and a one-time lifetime unlock. The exact product, duration, localized price, included features, and offer displayed by the App Store before confirmation control the purchase.","## 2. Payment","Payment is charged to the user's Apple Account after confirmation. Apple handles payment methods, taxes, currency, and receipts. Shield does not receive full payment-card details.","## 3. Renewal","Subscriptions renew automatically for the same period unless canceled at least 24 hours before the current period ends. Apple may charge the account within 24 hours before renewal at the displayed next-period price, subject to required notices and applicable law.","## 4. Trials and offers","Apple determines eligibility and displays the duration and post-offer price before confirmation. Unless canceled before it ends, an eligible trial converts to the shown paid subscription. An unused trial portion may be forfeited when another plan is purchased.","## 5. Manage, cancel, and restore","Manage or cancel in iOS Settings under Apple Account and Subscriptions, or through the App Store subscription page. Deleting Shield does not cancel. Cancellation stops future renewals and access normally continues through the paid period. Restore purchases in Shield while signed in with the purchasing Apple Account.","## 6. Refunds and billing","Apple handles refunds, billing disputes, grace periods, payment retries, and revocations under its policies and applicable law. Mandatory refund and withdrawal rights remain unaffected.","## 7. Lifetime unlock","The lifetime unlock is a non-consumable purchase granting the associated Pro features for the supported lifetime of Shield, not the purchaser's biological lifetime. It does not promise future products, third-party services, team plans, or separately priced services.","## 8. Changes","Apple and the developer may change future prices, plans, or included features. Apple supplies required notices and consent flows for subscription price increases. Completed non-consumable entitlements and mandatory rights remain unaffected.","## 9. Contact","Provider: **Lester Romero Bernardo (RomeroDev)**","Address: **Calle Madre Juana María Condesa Lluch 6, Valencia, Spain**","Support: **romerodev.app+shield@gmail.com**"]}},"pricing":[{"name":"Mensual","name_en":"Monthly","price":"2,99 €","cadence":"/mes","cadence_en":"/month","description":"Acceso flexible a Shield Pro.","description_en":"Flexible access to Shield Pro.","isIndicative":true},{"name":"Anual","name_en":"Annual","price":"29,99 €","cadence":"/año","cadence_en":"/year","description":"Incluye una prueba gratuita de 7 días para cuentas elegibles.","description_en":"Includes a 7-day free trial for eligible accounts.","badge":"Mejor valor","badge_en":"Best value","featured":true,"isIndicative":true},{"name":"De por vida","name_en":"Lifetime","price":"49,99 €","cadence":"pago único","cadence_en":"one-time","description":"Acceso permanente a Shield Pro.","description_en":"Permanent access to Shield Pro.","isIndicative":true}],"freeFeatures":["Importación, cámara y escáner","Máscaras manuales y sugerencias OCR","Exportación rasterizada y verificada","Cifrado local y Bóveda protegida","Hasta 10 documentos activos"],"freeFeatures_en":["Importing, camera, and scanner","Manual masks and OCR suggestions","Rasterized, verified export","Local encryption and protected Vault","Up to 10 active documents"],"proFeatures":["Proyectos activos ilimitados","Procesamiento por lotes","Plantillas semánticas reutilizables","Estilos y controles de imagen avanzados","Marcas de agua y automatizaciones"],"proFeatures_en":["Unlimited active projects","Batch processing","Reusable semantic templates","Advanced styles and image controls","Custom watermarks and automation"]}]$catalog$::jsonb;
  product jsonb;
  product_id uuid;
  faq_item jsonb;
  legal_item jsonb;
  faq_order integer;
begin
  for product in select value from jsonb_array_elements(catalog)
  loop
    insert into public.apps (
      slug, name, tagline, tagline_en, short_description, short_description_en,
      long_description, long_description_en, problem, problem_en, benefits,
      benefits_en, features, features_en, audience, audience_en, status,
      featured, category, platform, app_store_url, website_url, support_email,
      icon_url, cover_image_url, screenshots, video_url, primary_cta_label,
      primary_cta_label_en, primary_cta_url, secondary_cta_label,
      secondary_cta_label_en, secondary_cta_url, color_primary, color_secondary,
      seo_title, seo_description, seo_image, pricing, free_features,
      free_features_en, pro_features, pro_features_en, published_at, updated_at
    ) values (
      product->>'slug', product->>'name', product->>'tagline', product->>'tagline_en',
      product->>'shortDescription', product->>'shortDescription_en',
      product->>'longDescription', product->>'longDescription_en',
      product->>'problem', product->>'problem_en',
      array(select jsonb_array_elements_text(coalesce(product->'benefits', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'benefits_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'features_en', '[]'::jsonb))),
      product->>'audience', product->>'audience_en', product->>'status',
      coalesce((product->>'featured')::boolean, false), product->>'category',
      array(select jsonb_array_elements_text(coalesce(product->'platform', '[]'::jsonb))),
      nullif(product->>'appStoreUrl', ''), nullif(product->>'websiteUrl', ''),
      product->>'supportEmail', nullif(product->>'iconUrl', ''),
      nullif(product->>'coverImageUrl', ''),
      array(select jsonb_array_elements_text(coalesce(product->'screenshots', '[]'::jsonb))),
      nullif(product->>'videoUrl', ''), product->>'primaryCtaLabel',
      nullif(product->>'primaryCtaLabel_en', ''), product->>'primaryCtaUrl',
      nullif(product->>'secondaryCtaLabel', ''), nullif(product->>'secondaryCtaLabel_en', ''),
      nullif(product->>'secondaryCtaUrl', ''), nullif(product->>'colorPrimary', ''),
      nullif(product->>'colorSecondary', ''), product#>>'{seo,title}',
      product#>>'{seo,description}', nullif(product#>>'{seo,image}', ''),
      coalesce(product->'pricing', '[]'::jsonb),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'freeFeatures_en', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures', '[]'::jsonb))),
      array(select jsonb_array_elements_text(coalesce(product->'proFeatures_en', '[]'::jsonb))),
      nullif(product->>'publishedAt', '')::timestamptz, now()
    )
    on conflict (slug) do update set
      name = excluded.name, tagline = excluded.tagline, tagline_en = excluded.tagline_en,
      short_description = excluded.short_description, short_description_en = excluded.short_description_en,
      long_description = excluded.long_description, long_description_en = excluded.long_description_en,
      problem = excluded.problem, problem_en = excluded.problem_en, benefits = excluded.benefits,
      benefits_en = excluded.benefits_en, features = excluded.features, features_en = excluded.features_en,
      audience = excluded.audience, audience_en = excluded.audience_en, status = excluded.status,
      featured = excluded.featured, category = excluded.category, platform = excluded.platform,
      app_store_url = excluded.app_store_url, website_url = excluded.website_url,
      support_email = excluded.support_email, icon_url = excluded.icon_url,
      cover_image_url = excluded.cover_image_url, screenshots = excluded.screenshots,
      video_url = excluded.video_url, primary_cta_label = excluded.primary_cta_label,
      primary_cta_label_en = excluded.primary_cta_label_en, primary_cta_url = excluded.primary_cta_url,
      secondary_cta_label = excluded.secondary_cta_label,
      secondary_cta_label_en = excluded.secondary_cta_label_en,
      secondary_cta_url = excluded.secondary_cta_url, color_primary = excluded.color_primary,
      color_secondary = excluded.color_secondary, seo_title = excluded.seo_title,
      seo_description = excluded.seo_description, seo_image = excluded.seo_image,
      pricing = excluded.pricing, free_features = excluded.free_features,
      free_features_en = excluded.free_features_en, pro_features = excluded.pro_features,
      pro_features_en = excluded.pro_features_en, published_at = excluded.published_at,
      updated_at = now()
    returning id into product_id;

    delete from public.app_faqs where app_id = product_id;
    faq_order := 0;
    for faq_item in select value from jsonb_array_elements(coalesce(product->'faq', '[]'::jsonb))
    loop
      insert into public.app_faqs (app_id, question, question_en, answer, answer_en, sort_order)
      values (
        product_id, faq_item->>'question', nullif(faq_item->>'question_en', ''),
        faq_item->>'answer', nullif(faq_item->>'answer_en', ''), faq_order
      );
      faq_order := faq_order + 1;
    end loop;

    delete from public.app_legal_pages where app_id = product_id;
    for legal_item in
      select value from jsonb_array_elements(jsonb_build_array(
        jsonb_build_object('kind', 'privacy', 'page', product#>'{legal,privacy}'),
        jsonb_build_object('kind', 'terms', 'page', product#>'{legal,terms}'),
        jsonb_build_object('kind', 'subscriptions', 'page', product#>'{legal,subscriptions}')
      ))
    loop
      if legal_item->'page' is not null and legal_item->'page' <> 'null'::jsonb then
        insert into public.app_legal_pages (app_id, kind, title, title_en, body, body_en, updated_at)
        values (
          product_id, legal_item->>'kind', legal_item#>>'{page,title}',
          nullif(legal_item#>>'{page,title_en}', ''),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body}', '[]'::jsonb))), E'\n'),
          array_to_string(array(select jsonb_array_elements_text(coalesce(legal_item#>'{page,body_en}', '[]'::jsonb))), E'\n'),
          coalesce(nullif(legal_item#>>'{page,updatedAt}', '')::timestamptz, now())
        );
      end if;
    end loop;
  end loop;
end
$migration$;
